1	/**
2	 * @module evals/cases
3	 *
4	 * The eval set (E3): 13 cases covering the brief's questions, premise pushback,
5	 * follow-ups, scope limits, decisions and confidence. Every expected value comes
6	 * from the oracle at run time — nothing is hand-typed (E2).
7	 */
8	import { RECOMMENDATION_DISCLAIMER } from "../src/core/agent/config";
9	import { callsTo, check, firstHubMentioned, plainText, textHasNumber } from "./lib/checks";
10	import type { CheckResult, EvalCase, TurnResult } from "./lib/types";
11	
12	/** Every case must at least produce an answer (it passed validation within one retry). */
13	function answered(results: TurnResult[]): CheckResult[] {
14	  return results.map((r, i) =>
15	    check(`turn ${i + 1} answered`, !!r.answer, r.answer ? "validated answer produced" : `no answer: ${r.error ?? "unknown"}`),
16	  );
17	}
18	
19	/** Lower-case ids → names list, e.g. "Minneapolis, Detroit". */
20	const names = (ids: string[], hubs: { id: string; name: string }[]) => ids.map((id) => hubs.find((h) => h.id === id)?.name ?? id).join(", ");
21	
22	export const EVAL_CASES: EvalCase[] = [
23	  {
24	    id: "midwest-winter",
25	    title: "Midwest hubs most exposed to winter",
26	    turns: ["Which hubs in the Midwest are most exposed to winter disruption?"],
27	    check: ([r], o) => {
28	      const base = answered([r]);
29	      if (!r.answer) return base;
30	      const top = o.ranking("winter", "Midwest")[0];
31	      const first = firstHubMentioned(r.answer.answer, o.hubs);
32	      return [
33	        ...base,
34	        check("rank_hubs(winter, Midwest) called", callsTo(r.answer, "rank_hubs", (i) => i.metric === "winter" && i.region === "Midwest").length > 0, "expected a rank_hubs call with metric=winter, region=Midwest"),
35	        check("first hub named = computed #1", first === top, `expected ${names([top], o.hubs)}, answer led with ${first ?? "no hub"}`),
36	      ];
37	    },
38	  },
39	  {
40	    id: "miami-vs-houston",
41	    title: "Compare Miami and Houston (hurricane + flood)",
42	    turns: ["Compare Miami and Houston in terms of hurricane and flood exposure."],
43	    check: ([r], o) => {
44	      const base = answered([r]);
45	      if (!r.answer) return base;
46	      const miamiHurricane = o.hazardScore("miami", "hurricane");
47	      const houstonFlood = o.hazardScore("houston", "flood");
48	      return [
49	        ...base,
50	        check(
51	          "compare_hubs(miami, houston) called",
52	          callsTo(r.answer, "compare_hubs", (i) => Array.isArray(i.hubIds) && ["miami", "houston"].every((id) => (i.hubIds as string[]).includes(id))).length > 0,
53	          "expected compare_hubs with both hubs",
54	        ),
55	        check("Miami hurricane score matches", textHasNumber(r.answer.answer, miamiHurricane), `expected ${miamiHurricane} in the answer`),
56	        check("Houston flood score matches", textHasNumber(r.answer.answer, houstonFlood), `expected ${houstonFlood} in the answer`),
57	      ];
58	    },
59	  },
60	  {
61	    id: "denver-snow",
62	    title: "% of Denver days last year with snowfall",
63	    turns: ["What percentage of days in Denver last year had snowfall?"],
64	    check: async ([r], o) => {
65	      const base = answered([r]);
66	      if (!r.answer) return base;
67	      const expected = await o.yearPercent("denver", "measurable_snow_day", o.lastYear);
68	      return [
69	        ...base,
70	        check(
71	          `get_weather_stat(measurable snow, ${o.lastYear}) called`,
72	          callsTo(r.answer, "get_weather_stat", (i) => i.hubId === "denver" && i.metric === "measurable_snow_day" && i.year === o.lastYear).length > 0,
73	          `expected a measurable_snow_day stat for Denver in ${o.lastYear}`,
74	        ),
75	        check("percentage matches computed value", expected !== null && textHasNumber(r.answer.answer, expected), `expected ${expected}% in the answer`),
76	      ];
77	    },
78	  },
79	  {
80	    id: "dallas-why-high",
81	    title: "Why is Dallas's risk high? (premise check)",
82	    turns: ["Why is the Dallas hub's weather disruption risk high?"],
83	    check: ([r], o) => {
84	      const base = answered([r]);
85	      if (!r.answer) return base;
86	      const holds = o.level("dallas") === "high";
87	      return [
88	        ...base,
89	        check("explain_hub_score(dallas) called", callsTo(r.answer, "explain_hub_score", (i) => i.hubId === "dallas").length > 0, "expected explain_hub_score for Dallas"),
90	        check(
91	          "premise verdict matches Dallas's real level",
92	          r.answer.premiseCheck?.hubId === "dallas" && r.answer.premiseCheck.holds === holds,
93	          `expected premiseCheck.holds=${holds} (Dallas is ${o.level("dallas")}), got ${JSON.stringify(r.answer.premiseCheck)}`,
94	        ),
95	      ];
96	    },
97	  },
98	  {
99	    id: "seattle-false-premise",
100	    title: "False premise: Seattle hurricane risk",
101	    turns: ["Why is Seattle's hurricane risk so high?"],
102	    check: ([r], o) => {
103	      const base = answered([r]);
104	      if (!r.answer) return base;
105	      const actual = o.level("seattle", "hurricane");
106	      return [
107	        ...base,
108	        check(
109	          "premise flagged as wrong",
110	          r.answer.premiseCheck?.hubId === "seattle" && r.answer.premiseCheck.holds === false && actual !== "high",
111	          `expected holds=false (Seattle hurricane is ${actual}), got ${JSON.stringify(r.answer.premiseCheck)}`,
112	        ),
113	      ];
114	    },
115	  },
116	  {
117	    id: "follow-up",
118	    title: "Follow-up: 'Why that one?'",
119	    turns: ["Which Midwest hub is most exposed to winter weather?", "Why that one?"],
120	    check: (results, o) => {
121	      const base = answered(results);
122	      const second = results[1]?.answer;
123	      if (!second) return base;
124	      const top = o.ranking("winter", "Midwest")[0];
125	      const explained = callsTo(second, "explain_hub_score", (i) => i.hubId === top).length > 0;
126	      const named = firstHubMentioned(second.answer, o.hubs) === top;
127	      return [...base, check("turn 2 explains the computed #1 hub", explained || named, `expected the follow-up to be about ${names([top], o.hubs)}`)];
128	    },
129	  },
130	  {
131	    id: "top-5",
132	    title: "Top 5 hubs overall",
133	    turns: ["What are the 5 riskiest hubs overall?"],
134	    check: ([r], o) => {
135	      const base = answered([r]);
136	      if (!r.answer) return base;
137	      const top5 = o.ranking("overall").slice(0, 5);
138	      const missing = top5.filter((id) => !r.answer!.answer.includes(o.hubs.find((h) => h.id === id)!.name));
139	      return [...base, check("names the computed top 5", missing.length === 0, missing.length ? `missing: ${names(missing, o.hubs)}` : "all five named")];
140	    },
141	  },
142	  {
143	    id: "unknown-city",
144	    title: "City that isn't one of our hubs",
145	    turns: ["What is the weather risk at our Boise hub?"],
146	    check: ([r]) => {
147	      const base = answered([r]);
148	      if (!r.answer) return base;
149	      const said = /not (one of )?(our|the)\b[^.]{0,40}\bhubs?\b|not (one of )?our|isn't one of|is not a hub|don't (have|track|cover)|not in our (list|network)|no hub in boise/i.test(
150	        plainText(r.answer.answer),
151	      );
152	      return [
153	        ...base,
154	        check("says Boise isn't one of our hubs", said, "expected a plain 'not one of our hubs'"),
155	        check("no Boise numbers", !r.answer.hubsMentioned.includes("boise") && r.answer.dataUsed.every((d) => d.hubId !== "boise"), "no data may be attributed to Boise"),
156	      ];
157	    },
158	  },
159	  {
160	    id: "dust-storm",
161	    title: "Hazard we don't score (dust storms)",
162	    turns: ["How exposed is the Phoenix hub to dust storms?"],
163	    check: ([r]) => {
164	      const base = answered([r]);
165	      if (!r.answer) return base;
166	      const text = plainText(r.answer.answer);
167	      return [...base, check("says dust storms aren't scored", /dust/i.test(text) && /(not|n't)\b[^.]{0,80}(scor|cover|track|measur|includ|model)/i.test(text), "expected a plain statement that dust storms aren't scored")];
168	    },
169	  },
170	  {
171	    id: "decision",
172	    title: "Decision question (recommendation + disclaimer)",
173	    turns: ["Should we prioritize Houston or Denver for a resilience upgrade this year?"],
174	    check: ([r]) => {
175	      const base = answered([r]);
176	      if (!r.answer) return base;
177	      const rec = r.answer.recommendation;
178	      return [
179	        ...base,
180	        check("recommendation given", !!rec && rec.reasons.length > 0, "expected a recommendation with reasons"),
181	        check("code disclaimer attached", rec?.disclaimer === RECOMMENDATION_DISCLAIMER, "expected the fixed disclaimer"),
182	        check("backed by data", r.answer.dataUsed.length > 0, "expected numbers in dataUsed"),
183	      ];
184	    },
185	  },
186	  {
187	    id: "off-topic",
188	    title: "Off-topic request",
189	    turns: ["Write me a short poem about the sea."],
190	    check: ([r]) => {
191	      const base = answered([r]);
192	      if (!r.answer) return base;
193	      return [
194	        ...base,
195	        check("marked out of scope", r.answer.outOfScope, "expected outOfScope=true"),
196	        check("no tools called", r.answer.meta.toolCalls.length === 0, `expected 0 tool calls, got ${r.answer.meta.toolCalls.length}`),
197	      ];
198	    },
199	  },
200	  {
201	    id: "last-year",
202	    title: "'Last year' = previous calendar year",
203	    turns: ["How many heavy-rain days did Houston have last year?"],
204	    check: ([r], o) => {
205	      const base = answered([r]);
206	      if (!r.answer) return base;
207	      return [
208	        ...base,
209	        check(
210	          `stat for calendar ${o.lastYear}`,
211	          callsTo(r.answer, "get_weather_stat", (i) => i.hubId === "houston" && i.metric === "heavy_rain_day" && i.periodKind === "year" && i.year === o.lastYear).length > 0,
212	          `expected heavy_rain_day for Houston, year ${o.lastYear}`,
213	        ),
214	        check(`answer says ${o.lastYear}`, r.answer.answer.includes(String(o.lastYear)), `expected the year ${o.lastYear} in the text`),
215	      ];
216	    },
217	  },
218	  {
219	    id: "confidence",
220	    title: "Confidence explained (Seattle winter)",
221	    turns: ["How confident are you in Seattle's winter risk score?"],
222	    check: ([r], o) => {
223	      const base = answered([r]);
224	      if (!r.answer) return base;
225	      const expected = o.hazardConfidence("seattle", "winter");
226	      return [
227	        ...base,
228	        check("confidence = computed value", r.answer.confidence === expected, `expected ${expected}, got ${r.answer.confidence}`),
229	        check("explains why", /disagree|differ|mountain|two sources|Cascades|county/i.test(r.answer.answer), "expected the reason (sources disagree / mountain county)"),
230	      ];
231	    },
232	  },
233	];
