1	/**
2	 * @module evals/lib/suite
3	 *
4	 * Runs the whole eval set in this process and reports each case as it finishes (Step 16, D130).
5	 * Used by the app's "Run evals" button (POST /api/evals/run). The run summary it builds is also
6	 * what the CLI saves, so the "Answer quality" card shows the latest run from either.
7	 *
8	 * Cases run a few at a time (default 3), so a full run fits in a serverless function's time limit.
9	 */
10	import type { AgentContext } from "../../src/core/agent/context";
11	import type { AgentModel } from "../../src/core/agent/model";
12	import type { JudgeModel } from "../../src/core/judge/judgeAnswer";
13	import { EVAL_CASES } from "../cases";
14	import { judgeSelfTest, judgeTurns, type JudgeSelfTest } from "./judging";
15	import { buildOracle } from "./oracle";
16	import { runInProcess } from "./runners";
17	import type { CaseRun, EvalCase } from "./types";
18	
19	/** One case's outcome, as the card and the progress list show it. */
20	export interface CaseOutcome {
21	  caseId: string;
22	  title: string;
23	  pass: boolean;
24	  /** Names of the failed checks (empty when passed). */
25	  failed: string[];
26	  seconds: number;
27	}
28	
29	/** What a finished run is remembered by (saved in the `eval.finished` event as `summary`). */
30	export interface EvalRunSummary {
31	  model: string;
32	  trigger: "ui" | "cli";
33	  passed: number;
34	  total: number;
35	  /** The judge model, or null when the run had no judge. */
36	  judge: string | null;
37	  /** Whether the judge graded all planted answers right (null without a judge). */
38	  judgeReliable: boolean | null;
39	  seconds: number;
40	  finishedAt: string;
41	  cases: CaseOutcome[];
42	}
43	
44	/** Progress events, streamed to the browser one per line. */
45	export type SuiteEvent =
46	  | { type: "start"; total: number; model: string; judge: string | null; cases: { caseId: string; title: string }[] }
47	  | { type: "selftest"; correct: number; total: number }
48	  | { type: "case"; outcome: CaseOutcome }
49	  | { type: "done"; summary: EvalRunSummary };
50	
51	/**
52	 * One case's outcome from its run.
53	 * @param run - the case run.
54	 * @returns the outcome.
55	 */
56	export function caseOutcome(run: CaseRun): CaseOutcome {
57	  return {
58	    caseId: run.caseId,
59	    title: run.title,
60	    pass: run.pass,
61	    failed: run.checks.filter((c) => !c.pass).map((c) => c.name),
62	    seconds: Math.round(run.results.reduce((s, r) => s + r.ms, 0) / 100) / 10,
63	  };
64	}
65	
66	/**
67	 * The summary of a finished run (shared by the app and the CLI).
68	 * @param runs - the case runs.
69	 * @param meta - model, trigger, judge, self-test, duration.
70	 * @returns the summary.
71	 */
72	export function evalRunSummary(
73	  runs: CaseRun[],
74	  meta: { model: string; trigger: "ui" | "cli"; judge: string | null; selfTest: JudgeSelfTest | null; seconds: number },
75	): EvalRunSummary {
76	  return {
77	    model: meta.model,
78	    trigger: meta.trigger,
79	    passed: runs.filter((r) => r.pass).length,
80	    total: runs.length,
81	    judge: meta.judge,
82	    judgeReliable: meta.selfTest ? meta.selfTest.correct === meta.selfTest.total : null,
83	    seconds: Math.round(meta.seconds),
84	    finishedAt: new Date().toISOString(),
85	    cases: runs.map(caseOutcome),
86	  };
87	}
88	
89	/**
90	 * Checks that a saved event payload holds a run summary (older `eval.finished` events don't).
91	 * @param value - the payload's `summary` field.
92	 * @returns true when it has the summary's shape.
93	 */
94	export function isEvalRunSummary(value: unknown): value is EvalRunSummary {
95	  if (!value || typeof value !== "object") return false;
96	  const s = value as Partial<EvalRunSummary>;
97	  return typeof s.model === "string" && typeof s.passed === "number" && typeof s.total === "number" && typeof s.finishedAt === "string" && Array.isArray(s.cases);
98	}
99	
100	/**
101	 * The newest run summary among `eval.finished` events.
102	 * @param events - the events, newest first.
103	 * @returns the summary, or null when no event carries one.
104	 */
105	export function latestRunSummary(events: readonly { payload: unknown }[]): EvalRunSummary | null {
106	  for (const event of events) {
107	    const summary = (event.payload as { summary?: unknown } | null)?.summary;
108	    if (isEvalRunSummary(summary)) return summary;
109	  }
110	  return null;
111	}
112	
113	/** What a suite run needs. */
114	export interface SuiteOptions {
115	  agent: AgentModel;
116	  context: AgentContext;
117	  judge: JudgeModel | null;
118	  /** Cases run at the same time. */
119	  concurrency?: number;
120	  /** Called for each progress event. */
121	  onEvent: (event: SuiteEvent) => void;
122	  cases?: EvalCase[];
123	}
124	
125	/**
126	 * Runs the eval set once.
127	 * @param options - agent, data, judge, concurrency, progress callback.
128	 * @returns the case runs and the summary.
129	 */
130	export async function runEvalSuite(options: SuiteOptions): Promise<{ runs: CaseRun[]; summary: EvalRunSummary }> {
131	  const started = Date.now();
132	  const cases = options.cases ?? EVAL_CASES;
133	  const oracle = buildOracle(options.context);
134	  options.onEvent({
135	    type: "start",
136	    total: cases.length,
137	    model: options.agent.modelId,
138	    judge: options.judge?.modelId ?? null,
139	    cases: cases.map((c) => ({ caseId: c.id, title: c.title })),
140	  });
141	
142	  const selfTest = options.judge ? await judgeSelfTest(options.context, options.judge) : null;
143	  if (selfTest) options.onEvent({ type: "selftest", correct: selfTest.correct, total: selfTest.total });
144	
145	  const runs: CaseRun[] = new Array(cases.length);
146	  let next = 0;
147	  const worker = async () => {
148	    while (next < cases.length) {
149	      const index = next++;
150	      const evalCase = cases[index];
151	      const results = await runInProcess(evalCase, options.agent, options.context);
152	      const checks = await evalCase.check(results, oracle);
153	      const judged = options.judge ? await judgeTurns(results, options.judge, options.context) : null;
154	      const allChecks = [...checks, ...(judged?.checks ?? [])];
155	      const run: CaseRun = { caseId: evalCase.id, title: evalCase.title, results, checks: allChecks, pass: allChecks.every((c) => c.pass), judgments: judged?.judgments };
156	      runs[index] = run;
157	      options.onEvent({ type: "case", outcome: caseOutcome(run) });
158	    }
159	  };
160	  await Promise.all(Array.from({ length: Math.max(1, Math.min(options.concurrency ?? 3, cases.length)) }, worker));
161	
162	  const summary = evalRunSummary(runs, {
163	    model: options.agent.modelId,
164	    trigger: "ui",
165	    judge: options.judge?.modelId ?? null,
166	    selfTest,
167	    seconds: (Date.now() - started) / 1000,
168	  });
169	  options.onEvent({ type: "done", summary });
170	  return { runs, summary };
171	}
172

1	/**
2	 * @module scripts/eval
3	 *
4	 * `npm run eval` — runs the eval set (E1–E7) and prints pass/fail per case + totals.
5	 *
6	 *   npm run eval                              in-process, model from OPENROUTER_MODEL
7	 *   npm run eval -- --model=openai/gpt-6.1-terra   try another OpenRouter model (Step 8 bakeoff)
8	 *   npm run eval -- --repeat=3                run each case 3 times (consistency)
9	 *   npm run eval -- --case=denver-snow,top-5  only some cases
10	 *   npm run eval -- --url=https://…           against a deployed /api/chat
11	 *   npm run eval -- --publish                 also write docs/evals.md
12	 *   npm run eval -- --no-judge                skip the independent judge (J1–J4)
13	 *   npm run eval -- --rejudge=evals/results/<file>.json   re-check + re-judge saved answers, no agent calls (J8)
14	 *
15	 * Exit code 1 when any case fails. A JSON + Markdown report is saved in evals/results/.
16	 */
17	import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
18	import { join } from "node:path";
19	import { createAnswerQuestionDeps } from "../src/core/agent/createAnswerQuestionDeps";
20	import { getCronEnv } from "../src/core/config/env";
21	import { recordEvent } from "../src/core/db/eventsRepository";
22	import { createJudgeModel } from "../src/core/judge/judgeAnswer";
23	import { EVAL_CASES } from "../evals/cases";
24	import { baseModel } from "../evals/lib/bakeoff";
25	import { installStrayAbortGuard } from "../evals/lib/guards";
26	import { judgeSelfTest, judgeTurns } from "../evals/lib/judging";
27	import { buildOracle } from "../evals/lib/oracle";
28	import { fetchPricing, markdownSummary, printFloodReview, printJudgeReport, printReport, softMetrics } from "../evals/lib/report";
29	import { runInProcess, runRemote } from "../evals/lib/runners";
30	import { evalRunSummary } from "../evals/lib/suite";
31	import type { Json } from "../src/core/db/database.types";
32	import type { CaseRun, EvalCase, TurnResult } from "../evals/lib/types";
33	
34	/** Reads `--name=value` (or PowerShell's `npm_config_name`). */
35	function flag(name: string): string | undefined {
36	  const arg = process.argv.find((a) => a.startsWith(`--${name}=`));
37	  return arg ? arg.slice(name.length + 3) : process.env[`npm_config_${name}`];
38	}
39	
40	/** Reads a boolean `--name` flag. */
41	const has = (name: string) => process.argv.includes(`--${name}`) || process.env[`npm_config_${name}`] === "true";
42	
43	/** A results file written by an earlier run (evals/results/*.json). */
44	interface SavedRun {
45	  label: string;
46	  runs: CaseRun[];
47	}
48	
49	/**
50	 * Loads a saved results file for --rejudge.
51	 * @param path - path to the .json report.
52	 * @returns its label and runs.
53	 */
54	function loadSavedRun(path: string): SavedRun {
55	  const saved = JSON.parse(readFileSync(path, "utf8")) as SavedRun;
56	  if (!Array.isArray(saved.runs)) throw new Error(`${path} is not an eval results file (no "runs").`);
57	  return saved;
58	}
59	
60	/**
61	 * Finds an eval case by id.
62	 * @param id - case id.
63	 * @returns the case.
64	 */
65	function findCase(id: string): EvalCase {
66	  const found = EVAL_CASES.find((c) => c.id === id);
67	  if (!found) throw new Error(`Saved case "${id}" no longer exists in evals/cases.ts.`);
68	  return found;
69	}
70	
71	/** Runs the evals. */
72	async function main(): Promise<void> {
73	  installStrayAbortGuard();
74	  const startedAt = Date.now();
75	  const url = flag("url");
76	  const repeat = Math.max(1, Number(flag("repeat") ?? 1));
77	  const only = flag("case")?.split(",").map((s) => s.trim());
78	  const cases = only ? EVAL_CASES.filter((c) => only.includes(c.id)) : EVAL_CASES;
79	  if (cases.length === 0) throw new Error(`No cases match --case=${only?.join(",")}. Known: ${EVAL_CASES.map((c) => c.id).join(", ")}`);
80	
81	  // The oracle always reads the same data the agent sees (local DB access needed even in --url mode).
82	  const deps = createAnswerQuestionDeps({ modelOverride: flag("model") });
83	  const context = await deps.loadContext({ today: deps.today(), units: "us" });
84	  const oracle = buildOracle(context);
85	  const liveLabel = url ? `remote ${url}` : deps.agentModel.modelId;
86	  const rejudgeFile = flag("rejudge");
87	
88	  const judge = has("no-judge") ? null : createJudgeModel();
89	  const saved = rejudgeFile ? loadSavedRun(rejudgeFile) : null;
90	  const provider = (id: string) => id.split("/")[0];
91	  const answering = saved ? baseModel(saved.label) : url ? null : deps.agentModel.modelId;
92	  if (judge && answering && provider(judge.modelId) === provider(answering)) {
93	    console.warn(`⚠️  The judge (${judge.modelId}) and the answering model (${answering}) share a provider; judges can favor their own family (D100, D111).`);
94	  }
95	  const label = saved ? `${saved.label} (rejudged)` : liveLabel;
96	  console.log(
97	    saved
98	      ? `Re-checking ${saved.runs.length} saved run(s) from ${rejudgeFile}${judge ? `, judged by ${judge.modelId}` : ""}…`
99	      : `Running ${cases.length} case(s) × ${repeat} on ${label}${judge ? `, judged by ${judge.modelId}` : ""}…`,
100	  );
101	  const selfTest = judge ? await judgeSelfTest(context, judge) : null;
102	  // Each job yields one case's turn results: saved answers (--rejudge, no agent calls) or a fresh run.
103	  const jobs: { evalCase: EvalCase; getResults: () => Promise<TurnResult[]> }[] = saved
104	    ? saved.runs.map((run) => ({ evalCase: findCase(run.caseId), getResults: async () => run.results }))
105	    : Array.from({ length: repeat }, () => cases).flat().map((evalCase) => ({
106	        evalCase,
107	        getResults: () =>
108	          url
109	            ? runRemote(evalCase, { baseUrl: url, operatorKey: getCronEnv().CRON_SECRET })
110	            : runInProcess(evalCase, deps.agentModel, context),
111	      }));
112	  const runs: CaseRun[] = [];
113	  for (const { evalCase, getResults } of jobs) {
114	    const results = await getResults();
115	    const checks = await evalCase.check(results, oracle);
116	    const judged = judge ? await judgeTurns(results, judge, context) : null;
117	    const allChecks = [...checks, ...(judged?.checks ?? [])];
118	    const run = { caseId: evalCase.id, title: evalCase.title, results, checks: allChecks, pass: allChecks.every((c) => c.pass), judgments: judged?.judgments };
119	    runs.push(run);
120	    process.stdout.write(`${run.pass ? "." : "F"}`);
121	  }
122	
123	  const pricedModel = saved ? (saved.label.startsWith("remote") ? null : baseModel(saved.label)) : url ? null : deps.agentModel.modelId;
124	  const pricing = pricedModel ? await fetchPricing(pricedModel) : null;
125	  const metrics = softMetrics(runs, pricing);
126	  printReport(runs, metrics, `${label}${repeat > 1 ? ` · ${repeat} runs/case` : ""}`);
127	  printJudgeReport(runs, selfTest, judge?.modelId ?? null);
128	  printFloodReview(context);
129	
130	  const stamp = new Date().toISOString().replace(/[:.]/g, "-");
131	  const outDir = join("evals", "results");
132	  mkdirSync(outDir, { recursive: true });
133	  const fileBase = join(outDir, `${stamp}-${label.replace(/[^a-z0-9.-]+/gi, "_")}`);
134	  const markdown = markdownSummary(runs, metrics, {
135	    label,
136	    date: new Date().toISOString().slice(0, 16).replace("T", " ") + " UTC",
137	    repeat,
138	    judgeModel: judge?.modelId ?? null,
139	    selfTest,
140	  });
141	  writeFileSync(`${fileBase}.json`, JSON.stringify({ label, repeat, metrics, judge: judge?.modelId ?? null, selfTest, runs }, null, 2));
142	  writeFileSync(`${fileBase}.md`, markdown);
143	  if (has("publish")) writeFileSync(join("docs", "evals.md"), markdown);
144	  console.log(`\nReport: ${fileBase}.md${has("publish") ? " (+ docs/evals.md)" : ""}`);
145	
146	  const failed = runs.filter((r) => !r.pass);
147	  await recordEvent({
148	    eventType: "eval.finished",
149	    source: "eval",
150	    level: failed.length ? "warn" : "info",
151	    message: `${runs.length - failed.length}/${runs.length} runs passed on ${label}`,
152	    payload: {
153	      label,
154	      repeat,
155	      failedCases: [...new Set(failed.map((r) => r.caseId))],
156	      avgToolCalls: metrics.avgToolCalls,
157	      costUsd: metrics.costUsd,
158	      judge: judge?.modelId ?? null,
159	      judgeSelfTest: selfTest ? `${selfTest.correct}/${selfTest.total}` : null,
160	      // The same summary the app saves, so the "Answer quality" card shows CLI runs too (D130).
161	      // Saved only for a single, live, in-process run: that's what the card describes.
162	      summary:
163	        repeat === 1 && !url && !saved
164	          ? (evalRunSummary(runs, { model: label, trigger: "cli", judge: judge?.modelId ?? null, selfTest, seconds: (Date.now() - startedAt) / 1000 }) as unknown as Json)
165	          : null,
166	    },
167	  });
168	  if (failed.length) process.exit(1);
169	}
170	
171	main().catch((error: unknown) => {
172	  console.error(error instanceof Error ? error.message : error);
173	  process.exit(1);
174	});
