1	/**
2	 * @module evals/lib/report
3	 *
4	 * Soft metrics (E4), the terminal table and the Markdown summary (E6), and the
5	 * flood side-by-side for the D57 review (E7).
6	 */
7	import type { AgentContext } from "../../src/core/agent/context";
8	import { duplicateCalls } from "./checks";
9	import { isInconsistentVerdict } from "../../src/core/judge/judgeAnswer";
10	import type { JudgeSelfTest } from "./judging";
11	import type { CaseRun } from "./types";
12	
13	/** Price per token, from OpenRouter's public model list (null when unknown). */
14	export interface Pricing {
15	  input: number;
16	  output: number;
17	}
18	
19	/**
20	 * Looks up a model's current price on OpenRouter (public endpoint, no key).
21	 * @param modelId - OpenRouter model id.
22	 * @returns per-token prices, or null when unavailable.
23	 */
24	export async function fetchPricing(modelId: string): Promise<Pricing | null> {
25	  try {
26	    const res = await fetch("https://openrouter.ai/api/v1/models", { signal: AbortSignal.timeout(15_000) });
27	    const json = (await res.json()) as { data: { id: string; pricing: { prompt: string; completion: string } }[] };
28	    const model = json.data.find((m) => m.id === modelId);
29	    return model ? { input: Number(model.pricing.prompt), output: Number(model.pricing.completion) } : null;
30	  } catch {
31	    return null;
32	  }
33	}
34	
35	/** Soft metrics for a set of runs. */
36	export interface SoftMetrics {
37	  turns: number;
38	  avgToolCalls: number;
39	  duplicateCalls: number;
40	  untracedNumbers: number;
41	  retries: number;
42	  avgSeconds: number;
43	  p95Seconds: number;
44	  inputTokens: number;
45	  outputTokens: number;
46	  /** Estimated USD, null when pricing/usage is unknown. */
47	  costUsd: number | null;
48	}
49	
50	/**
51	 * Computes the soft metrics over all turns of all runs.
52	 * @param runs - case runs.
53	 * @param pricing - per-token prices (or null).
54	 * @returns the metrics.
55	 */
56	export function softMetrics(runs: CaseRun[], pricing: Pricing | null): SoftMetrics {
57	  const turns = runs.flatMap((r) => r.results);
58	  const answers = turns.map((t) => t.answer).filter((a) => a !== null);
59	  const seconds = turns.map((t) => t.ms / 1000).sort((a, b) => a - b);
60	  const inputTokens = turns.reduce((s, t) => s + (t.usage?.inputTokens ?? 0), 0);
61	  const outputTokens = turns.reduce((s, t) => s + (t.usage?.outputTokens ?? 0), 0);
62	  const hasUsage = turns.some((t) => t.usage);
63	  return {
64	    turns: turns.length,
65	    avgToolCalls: answers.length ? answers.reduce((s, a) => s + a.meta.toolCalls.length, 0) / answers.length : 0,
66	    duplicateCalls: answers.reduce((s, a) => s + duplicateCalls(a.meta.toolCalls), 0),
67	    untracedNumbers: answers.reduce((s, a) => s + a.meta.warnings.length, 0),
68	    retries: answers.filter((a) => a.meta.retried).length,
69	    avgSeconds: seconds.reduce((s, x) => s + x, 0) / Math.max(1, seconds.length),
70	    p95Seconds: seconds[Math.min(seconds.length - 1, Math.floor(seconds.length * 0.95))] ?? 0,
71	    inputTokens,
72	    outputTokens,
73	    costUsd: pricing && hasUsage ? inputTokens * pricing.input + outputTokens * pricing.output : null,
74	  };
75	}
76	
77	/** Formats a number to fixed decimals. */
78	const f = (n: number, d = 1) => n.toFixed(d);
79	
80	/**
81	 * Token counts as text. A remote run (`--url`) can't see them: the streamed API doesn't carry usage.
82	 * @param metrics - soft metrics.
83	 * @returns "in / out", or a plain "n/a" explanation.
84	 */
85	function tokensText(metrics: SoftMetrics): string {
86	  if (metrics.inputTokens === 0 && metrics.outputTokens === 0) return "n/a (remote run: the API stream doesn't report tokens)";
87	  return `${metrics.inputTokens.toLocaleString()} in / ${metrics.outputTokens.toLocaleString()} out`;
88	}
89	
90	/**
91	 * Prints the per-case table and the totals to the terminal.
92	 * @param runs - case runs.
93	 * @param metrics - soft metrics.
94	 * @param label - model / target label.
95	 */
96	export function printReport(runs: CaseRun[], metrics: SoftMetrics, label: string): void {
97	  console.log(`\n🔮 Sneakoscope evals — ${label}\n`);
98	  for (const run of runs) {
99	    const answers = run.results.map((r) => r.answer).filter((a) => a !== null);
100	    const tools = answers.reduce((s, a) => s + a.meta.toolCalls.length, 0);
101	    const dupes = answers.reduce((s, a) => s + duplicateCalls(a.meta.toolCalls), 0);
102	    const secs = run.results.reduce((s, r) => s + r.ms, 0) / 1000;
103	    console.log(`${run.pass ? "✅" : "❌"} ${run.caseId.padEnd(22)} ${run.title.padEnd(48)} tools ${tools}${dupes ? ` (${dupes} dup)` : ""} · ${f(secs)}s`);
104	    for (const c of run.checks.filter((c) => !c.pass)) console.log(`     ✗ ${c.name}: ${c.detail}`);
105	  }
106	  const passed = runs.filter((r) => r.pass).length;
107	  console.log(`\n${passed === runs.length ? "🏆" : "⚠️ "} ${passed}/${runs.length} cases passed`);
108	  console.log(
109	    `   avg ${f(metrics.avgToolCalls)} tool calls · ${metrics.duplicateCalls} duplicate calls · ${metrics.untracedNumbers} untraced numbers · ` +
110	      `${metrics.retries} retries · avg ${f(metrics.avgSeconds)}s (p95 ${f(metrics.p95Seconds)}s) · ` +
111	      `tokens ${tokensText(metrics)}` +
112	      (metrics.costUsd !== null ? ` · ≈ $${f(metrics.costUsd, 3)}` : ""),
113	  );
114	}
115	
116	/** Average judge scores over all judged turns (J3 soft metrics). */
117	export interface JudgeAverages {
118	  judged: number;
119	  faithfulToData: number;
120	  answersQuestion: number;
121	  honestAboutLimits: number;
122	  premiseHandling: number | null;
123	  clarity: number;
124	  /** Answers the judge gave a "pass" verdict (soft, J5). */
125	  passVerdicts: number;
126	  /** Claims about our data the judge found unsupported. */
127	  unsupportedClaims: number;
128	  /** Widely known context, allowed but listed (J6). */
129	  generalKnowledgeClaims: number;
130	  /** Verdicts that contradict themselves (D109): a sign the judge is broken. */
131	  inconsistent: number;
132	}
133	
134	/**
135	 * Averages the judge's scores across every judged turn.
136	 * @param runs - case runs with judgments.
137	 * @returns averages, or null when nothing was judged.
138	 */
139	export function judgeAverages(runs: CaseRun[]): JudgeAverages | null {
140	  const verdicts = runs.flatMap((r) => r.judgments ?? []).map((j) => j.verdict).filter((v) => v !== null);
141	  if (verdicts.length === 0) return null;
142	  const avg = (pick: (v: (typeof verdicts)[number]) => number | null) => {
143	    const values = verdicts.map(pick).filter((x): x is number => x !== null);
144	    return values.length ? values.reduce((a, b) => a + b, 0) / values.length : null;
145	  };
146	  return {
147	    judged: verdicts.length,
148	    faithfulToData: avg((v) => v.faithfulToData)!,
149	    answersQuestion: avg((v) => v.answersQuestion)!,
150	    honestAboutLimits: avg((v) => v.honestAboutLimits)!,
151	    premiseHandling: avg((v) => v.premiseHandling),
152	    clarity: avg((v) => v.clarity)!,
153	    passVerdicts: verdicts.filter((v) => v.verdict === "pass").length,
154	    unsupportedClaims: verdicts.reduce((s, v) => s + v.unsupportedClaims.length, 0),
155	    generalKnowledgeClaims: verdicts.reduce((s, v) => s + v.generalKnowledgeClaims.length, 0),
156	    inconsistent: verdicts.filter(isInconsistentVerdict).length,
157	  };
158	}
159	
160	/**
161	 * Prints the judge's average scores and the self-test (J3, J4).
162	 * @param runs - case runs.
163	 * @param selfTest - the self-test result (null when the judge is off).
164	 * @param judgeModel - judge model id (null when off).
165	 */
166	export function printJudgeReport(runs: CaseRun[], selfTest: JudgeSelfTest | null, judgeModel: string | null): void {
167	  if (!judgeModel) return console.log("\n⚖️  Judge: off (--no-judge)");
168	  const a = judgeAverages(runs);
169	  const reliable = selfTest !== null && selfTest.correct === selfTest.total && (a?.inconsistent ?? 0) === 0;
170	  console.log(`\n⚖️  Judge (${judgeModel}) — self-test: ${selfTest ? `${selfTest.correct}/${selfTest.total} planted answers graded right` : "n/a"}${reliable ? " ✅" : " ⚠️  JUDGE UNRELIABLE — don't trust its verdicts"}`);
171	  for (const d of selfTest?.details ?? []) console.log(`   · ${d}`);
172	  if (a) {
173	    console.log(
174	      `   avg over ${a.judged} answers (1–5): faithful ${f(a.faithfulToData)} · answers question ${f(a.answersQuestion)} · ` +
175	        `honest about limits ${f(a.honestAboutLimits)} · premise ${a.premiseHandling === null ? "n/a" : f(a.premiseHandling)} · clarity ${f(a.clarity)}`,
176	    );
177	    console.log(
178	      `   "pass" verdicts ${a.passVerdicts}/${a.judged} (soft) · ${a.unsupportedClaims} unsupported claims · ${a.generalKnowledgeClaims} general-knowledge claims (allowed)` +
179	        (a.inconsistent ? ` · ⚠️  ${a.inconsistent} self-contradicting verdicts` : ""),
180	    );
181	    for (const run of runs) {
182	      for (const j of run.judgments ?? []) {
183	        for (const claim of j.verdict?.unsupportedClaims ?? []) console.log(`   ⚑ ${run.caseId}: ${claim}`);
184	      }
185	    }
186	  }
187	}
188	
189	/**
190	 * Builds the Markdown summary committed as docs/evals.md (E6).
191	 * @param runs - case runs.
192	 * @param metrics - soft metrics.
193	 * @param meta - model, mode, date, repeat count.
194	 * @returns Markdown.
195	 */
196	export function markdownSummary(
197	  runs: CaseRun[],
198	  metrics: SoftMetrics,
199	  meta: { label: string; date: string; repeat: number; judgeModel: string | null; selfTest: JudgeSelfTest | null },
200	): string {
201	  const byCase = new Map<string, CaseRun[]>();
202	  for (const run of runs) byCase.set(run.caseId, [...(byCase.get(run.caseId) ?? []), run]);
203	  const rows = [...byCase.values()].map((caseRuns) => {
204	    const passes = caseRuns.filter((r) => r.pass).length;
205	    const failed = caseRuns.flatMap((r) => r.checks.filter((c) => !c.pass).map((c) => c.name));
206	    return `| ${caseRuns[0].caseId} | ${caseRuns[0].title} | ${passes === caseRuns.length ? "✅" : "❌"} ${passes}/${caseRuns.length} | ${[...new Set(failed)].join("; ") || "—"} |`;
207	  });
208	  const passedCases = [...byCase.values()].filter((rs) => rs.every((r) => r.pass)).length;
209	  return `# Eval results
210	
211	Latest run: **${meta.label}** · ${meta.date} · ${meta.repeat} run(s) per case.
212	Run it yourself: \`npm run eval\` (see [README](../README.md)). Expected values are computed from the live data at run time.
213	
214	**${passedCases}/${byCase.size} cases passed** (a case passes only if every run passed).
215	
216	| Case | What it checks | Result | Failed checks |
217	|---|---|---|---|
218	${rows.join("\n")}
219	
220	## Soft metrics (not pass/fail)
221	| Metric | Value |
222	|---|---|
223	| Avg tool calls per answer | ${f(metrics.avgToolCalls)} |
224	| Duplicate tool calls (total) | ${metrics.duplicateCalls} |
225	| Numbers in text not traced to tools | ${metrics.untracedNumbers} |
226	| Answers that needed a validation retry | ${metrics.retries} |
227	| Avg / p95 seconds per answer | ${f(metrics.avgSeconds)} / ${f(metrics.p95Seconds)} |
228	| Tokens (in / out) | ${tokensText(metrics)} |
229	| Estimated cost | ${metrics.costUsd !== null ? `$${f(metrics.costUsd, 3)}` : "n/a"} |
230	${judgeSection(runs, meta.judgeModel, meta.selfTest)}`;
231	}
232	
233	/** The judge section of the Markdown summary. */
234	function judgeSection(runs: CaseRun[], judgeModel: string | null, selfTest: JudgeSelfTest | null): string {
235	  if (!judgeModel) return "\n## Independent judge\nNot run (`--no-judge`).\n";
236	  const a = judgeAverages(runs);
237	  const reliable = selfTest !== null && selfTest.correct === selfTest.total && (a?.inconsistent ?? 0) === 0;
238	  const flagged = runs.flatMap((r) =>
239	    (r.judgments ?? []).flatMap((j) => (j.verdict?.unsupportedClaims ?? []).map((claim) => `- \`${r.caseId}\`: ${claim.replace(/\|/g, "\\|")}`)),
240	  );
241	  return `
242	## Independent judge
243	Each answer is graded by **${judgeModel}** (a different provider than the answering model) against the actual tool results.
244	Hard check: faithful to data ≥ 4 (included in the results above). Everything else here is a soft metric:
245	graded twice on identical answers, the pass/fail verdict flipped on 4 of 14, so it can't fail a case on its own (D103).
246	
247	**Judge self-test:** ${selfTest ? `${selfTest.correct}/${selfTest.total} planted answers graded right` : "n/a"} ${reliable ? "✅ — the judge's verdicts can be trusted" : "⚠️ — the judge misgraded a planted answer or contradicted itself, treat its verdicts with caution"}
248	${(selfTest?.details ?? []).map((d) => `- ${d}`).join("\n")}
249	${
250	  a
251	    ? `
252	| Average score (1–5) over ${a.judged} answers | |
253	|---|---|
254	| Faithful to data | ${f(a.faithfulToData)} |
255	| Answers the question | ${f(a.answersQuestion)} |
256	| Honest about limits | ${f(a.honestAboutLimits)} |
257	| Premise handling (when there was one) | ${a.premiseHandling === null ? "n/a" : f(a.premiseHandling)} |
258	| Clarity | ${f(a.clarity)} |
259	| "Pass" verdicts | ${a.passVerdicts}/${a.judged} |
260	| Unsupported claims about our data | ${a.unsupportedClaims} |
261	| General-knowledge claims (allowed, D104) | ${a.generalKnowledgeClaims} |
262	| Self-contradicting verdicts (D109) | ${a.inconsistent} |
263	`
264	    : ""
265	}${flagged.length ? `\n**Claims the judge flagged as unsupported** (to review, not all are errors):\n${flagged.join("\n")}\n` : ""}`;
266	}
