1	/**
2	 * @module evals/lib/judging
3	 *
4	 * Runs the independent judge over eval answers (J1–J3) and tests the judge
5	 * itself with planted bad answers (J4): a judge that passes a wrong number or a
6	 * swallowed false premise can't be trusted, and the report says so.
7	 */
8	import type { FinalAnswer } from "../../src/core/agent/answerSchema";
9	import type { AgentContext } from "../../src/core/agent/context";
10	import { buildSystemPrompt } from "../../src/core/agent/systemPrompt";
11	import { explainHubScoreOutput } from "../../src/core/agent/tools/explainHubScore";
12	import { describeUnknownError } from "../../src/core/errors/boundaryError";
13	import { isInconsistentVerdict, judgeAnswer, judgePasses, type JudgeModel, type JudgeVerdict } from "../../src/core/judge/judgeAnswer";
14	import { check } from "./checks";
15	import type { CheckResult, TurnResult } from "./types";
16	
17	/** The judge's verdict for one turn (or why there is none). */
18	export interface TurnJudgment {
19	  question: string;
20	  verdict: JudgeVerdict | null;
21	  error?: string;
22	}
23	
24	/**
25	 * Judges every answered turn of a case run. The judge sees what the agent saw:
26	 * its system prompt and, in follow-ups, earlier turns' tool results (D65).
27	 * @param results - the case's turns.
28	 * @param judge - the judge model.
29	 * @param ctx - agent context (to rebuild the agent's system prompt).
30	 * @returns judgments and the matching hard checks (J3: pass AND faithful ≥ 4).
31	 */
32	export async function judgeTurns(
33	  results: TurnResult[],
34	  judge: JudgeModel,
35	  ctx: AgentContext,
36	): Promise<{ judgments: TurnJudgment[]; checks: CheckResult[] }> {
37	  const briefing = buildSystemPrompt(ctx);
38	  const judgments: TurnJudgment[] = [];
39	  const checks: CheckResult[] = [];
40	  for (const [i, turn] of results.entries()) {
41	    if (!turn.answer) continue;
42	    const earlierToolCalls = results.slice(0, i).flatMap((r) => r.answer?.meta.toolCalls ?? []);
43	    try {
44	      const verdict = await judgeAnswer(turn.question, turn.answer, judge, { briefing, earlierToolCalls });
45	      judgments.push({ question: turn.question, verdict });
46	      const unsupported = verdict.unsupportedClaims.length ? ` · unsupported: ${verdict.unsupportedClaims.join("; ")}` : "";
47	      const contradiction = isInconsistentVerdict(verdict) ? " · ⚠️ JUDGE CONTRADICTED ITSELF (pass, but low score and no unsupported claims)" : "";
48	      checks.push(
49	        check(
50	          `judge: turn ${i + 1} faithful to data`,
51	          judgePasses(verdict),
52	          `verdict ${verdict.verdict}, faithful ${verdict.faithfulToData}/5 — ${verdict.reason}${unsupported}${contradiction}`,
53	        ),
54	      );
55	    } catch (error) {
56	      judgments.push({ question: turn.question, verdict: null, error: describeUnknownError(error) });
57	      checks.push(check(`judge: turn ${i + 1} faithful to data`, false, `judge unavailable: ${describeUnknownError(error)}`));
58	    }
59	  }
60	  return { judgments, checks };
61	}
62	
63	/** Result of the judge self-test (J4, D109). */
64	export interface JudgeSelfTest {
65	  /** Planted answers the judge graded right (bad ones failed, the good one passed). */
66	  correct: number;
67	  total: number;
68	  details: string[];
69	}
70	
71	/** A minimal answer built around one real tool result. */
72	function plantedAnswer(text: string, tool: string, input: object, output: unknown, premiseCheck: FinalAnswer["premiseCheck"]): FinalAnswer {
73	  return {
74	    answer: text,
75	    outOfScope: false,
76	    hubsMentioned: [],
77	    dataUsed: [],
78	    premiseCheck,
79	    confidence: "high",
80	    assumptions: [],
81	    limitations: [],
82	    followUpSuggestions: [],
83	    recommendation: null,
84	    meta: { model: "planted", toolCalls: [{ tool, input, output }], warnings: [], retried: false, confidenceOverridden: false },
85	  };
86	}
87	
88	/**
89	 * Plants answers built on REAL tool results and checks the judge grades them right (J4, D109):
90	 * two clearly bad ones must fail, and one correct one must pass. Without the good one, a judge
91	 * that fails everything looks perfect (a Qwen judge did exactly that in the bakeoff).
92	 * @param ctx - agent context (real data).
93	 * @param judge - the judge model.
94	 * @returns how many planted answers the judge graded right.
95	 */
96	export async function judgeSelfTest(ctx: AgentContext, judge: JudgeModel): Promise<JudgeSelfTest> {
97	  const dallas = explainHubScoreOutput(ctx, { hubId: "dallas" });
98	  const seattle = explainHubScoreOutput(ctx, { hubId: "seattle" });
99	  const wrongScore = Math.round((dallas.overallScore + 15.3) * 10) / 10;
100	  const dallasIsHigh = dallas.level === "high";
101	  const planted: { label: string; question: string; answer: FinalAnswer; shouldPass: boolean }[] = [
102	    {
103	      label: "correct answer (Dallas) must PASS",
104	      question: "Why is the Dallas hub's weather disruption risk high?",
105	      shouldPass: true,
106	      answer: plantedAnswer(
107	        `${dallasIsHigh ? "Yes" : "Actually, it isn't"}: Dallas's overall score is ${dallas.overallScore}, rated ${dallas.level}, ` +
108	          `ranking ${dallas.rankOverall} of ${dallas.totalHubs} hubs. Its worst hazard is ${dallas.topHazard}, and the formula adds ` +
109	          `0.4 × the worst hazard score so one severe hazard is not averaged away.`,
110	        "explain_hub_score",
111	        { hubId: "dallas" },
112	        dallas,
113	        { hubId: "dallas", hazard: null, claimedLevel: "high", actualLevel: dallas.level, holds: dallasIsHigh },
114	      ),
115	    },
116	    {
117	      label: "wrong number + wrong driver (Dallas) must FAIL",
118	      shouldPass: false,
119	      question: "Why is the Dallas hub's weather disruption risk high?",
120	      answer: plantedAnswer(
121	        `Dallas scores ${wrongScore} overall, ranking 1st of 36 hubs, driven mostly by hurricanes.`,
122	        "explain_hub_score",
123	        { hubId: "dallas" },
124	        dallas,
125	        { hubId: "dallas", hazard: null, claimedLevel: "high", actualLevel: dallas.level, holds: dallas.level === "high" },
126	      ),
127	    },
128	    {
129	      label: "swallowed a false premise (Seattle hurricanes) must FAIL",
130	      shouldPass: false,
131	      question: "Why is Seattle's hurricane risk so high?",
132	      answer: plantedAnswer(
133	        "Seattle's hurricane risk is high because Pacific storms regularly bring hurricane-force conditions to the hub.",
134	        "explain_hub_score",
135	        { hubId: "seattle" },
136	        seattle,
137	        { hubId: "seattle", hazard: "hurricane", claimedLevel: "high", actualLevel: "low", holds: false },
138	      ),
139	    },
140	  ];
141	  const details: string[] = [];
142	  let correct = 0;
143	  for (const p of planted) {
144	    try {
145	      const verdict = await judgeAnswer(p.question, p.answer, judge, { briefing: buildSystemPrompt(ctx), earlierToolCalls: [] });
146	      const right = judgePasses(verdict) === p.shouldPass;
147	      if (right) correct++;
148	      details.push(`${right ? "right" : "WRONG"}: ${p.label} (verdict ${verdict.verdict}, faithful ${verdict.faithfulToData}/5)`);
149	    } catch (error) {
150	      details.push(`ERROR: ${p.label} — ${describeUnknownError(error)}`);
151	    }
152	  }
153	  return { correct, total: planted.length, details };
154	}
