1	/**
2	 * @module evals/lib/bakeoff
3	 *
4	 * Pools saved eval runs per model and ranks models by the agreed rule (B4, D107):
5	 * 1) gate: zero failures on premise/data checks and p95 ≤ 30 s;
6	 * 2) accuracy: pass rate, where within 2 case-runs of the best counts as a tie;
7	 * 3) cheapest per answer among the tied; 4) fastest as the final tiebreak.
8	 */
9	import { judgeAverages, softMetrics } from "./report";
10	import type { CaseRun } from "./types";
11	
12	/** Hard UX limit on p95 seconds per answer (B4). */
13	export const P95_LIMIT_SECONDS = 30;
14	
15	/** Case-runs within this many of the best pass count are a tie (B4: noise). */
16	export const TIE_BAND_RUNS = 2;
17	
18	/** Check names that guard the "never wrong" promises: the premise verdict and the data (B4 gate). */
19	export const GATE_CHECK = /premise|matches|computed|numbers|percentage/i;
20	
21	/** A saved eval results file (scripts/eval.ts output). */
22	export interface ResultsFile {
23	  label: string;
24	  judge: string | null;
25	  /** The judge's self-test (`correct`; files from before D109 have `caught`). */
26	  selfTest?: { correct?: number; caught?: number; total: number } | null;
27	  metrics: { turns: number; costUsd: number | null };
28	  runs: CaseRun[];
29	}
30	
31	/**
32	 * The model id behind a results label ("x/y (rejudged) (rejudged)" → "x/y").
33	 * @param label - a results file label.
34	 * @returns the model id.
35	 */
36	export function baseModel(label: string): string {
37	  return label.replace(/( \(rejudged\))+$/, "");
38	}
39	
40	/**
41	 * Whether a judge was reliable on these files (D109): every self-test fully right and no self-contradicting verdicts.
42	 * @param files - results graded by one judge.
43	 * @returns true when the judge can be trusted.
44	 */
45	export function judgeReliable(files: ResultsFile[]): boolean {
46	  const selfTestsOk = files.every((f) => f.selfTest && (f.selfTest.correct ?? f.selfTest.caught) === f.selfTest.total);
47	  return selfTestsOk && (judgeAverages(files.flatMap((f) => f.runs))?.inconsistent ?? 0) === 0;
48	}
49	
50	/** One model's pooled results. */
51	export interface ModelSummary {
52	  model: string;
53	  caseRuns: number;
54	  passed: number;
55	  gateFailures: string[];
56	  codeFailures: number;
57	  judgeFailures: number;
58	  answers: number;
59	  costPerAnswer: number | null;
60	  avgSeconds: number;
61	  p95Seconds: number;
62	  avgToolCalls: number;
63	  duplicateCalls: number;
64	  untraced: number;
65	  retries: number;
66	  faithful: number | null;
67	  /** Self-contradicting judge verdicts (D109). */
68	  judgeInconsistent: number;
69	  failedCases: string[];
70	}
71	
72	/**
73	 * Pools one model's files into a summary.
74	 * @param model - model id.
75	 * @param files - that model's results files.
76	 * @returns the summary.
77	 */
78	export function summarize(model: string, files: ResultsFile[]): ModelSummary {
79	  const runs = files.flatMap((f) => f.runs);
80	  const metrics = softMetrics(runs, null);
81	  // Cost per answer from the files that have a price (a re-judged file may not).
82	  const priced = files.filter((f) => f.metrics.costUsd !== null);
83	  const pricedTurns = priced.reduce((s, f) => s + f.metrics.turns, 0);
84	  const costPerAnswer = pricedTurns ? priced.reduce((s, f) => s + f.metrics.costUsd!, 0) / pricedTurns : null;
85	  const failed = runs.flatMap((r) => r.checks.filter((c) => !c.pass).map((c) => ({ caseId: r.caseId, name: c.name })));
86	  return {
87	    model,
88	    caseRuns: runs.length,
89	    passed: runs.filter((r) => r.pass).length,
90	    gateFailures: failed.filter((c) => !c.name.startsWith("judge:") && GATE_CHECK.test(c.name)).map((c) => `${c.caseId}: ${c.name}`),
91	    codeFailures: failed.filter((c) => !c.name.startsWith("judge:")).length,
92	    judgeFailures: failed.filter((c) => c.name.startsWith("judge:")).length,
93	    answers: metrics.turns,
94	    costPerAnswer,
95	    avgSeconds: metrics.avgSeconds,
96	    p95Seconds: metrics.p95Seconds,
97	    avgToolCalls: metrics.avgToolCalls,
98	    duplicateCalls: metrics.duplicateCalls,
99	    untraced: metrics.untracedNumbers,
100	    retries: metrics.retries,
101	    faithful: judgeAverages(runs)?.faithfulToData ?? null,
102	    judgeInconsistent: judgeAverages(runs)?.inconsistent ?? 0,
103	    failedCases: [...new Set(runs.filter((r) => !r.pass).map((r) => r.caseId))],
104	  };
105	}
106	
107	/**
108	 * Orders models by the B4 rule and says why each one lands where it does.
109	 * @param models - model summaries.
110	 * @returns ranked summaries with a short verdict each.
111	 */
112	export function rankModels(models: ModelSummary[]): { summary: ModelSummary; verdict: string }[] {
113	  const rate = (m: ModelSummary) => m.passed / Math.max(1, m.caseRuns);
114	  const gated = (m: ModelSummary) => m.gateFailures.length === 0 && m.p95Seconds <= P95_LIMIT_SECONDS;
115	  const eligible = models.filter(gated);
116	  const best = Math.max(0, ...eligible.map(rate));
117	  const tied = (m: ModelSummary) => gated(m) && rate(m) >= best - TIE_BAND_RUNS / Math.max(1, m.caseRuns);
118	  const order = (a: ModelSummary, b: ModelSummary) =>
119	    Number(tied(b)) - Number(tied(a)) ||
120	    Number(gated(b)) - Number(gated(a)) ||
121	    (tied(a) && tied(b) ? (a.costPerAnswer ?? Infinity) - (b.costPerAnswer ?? Infinity) || a.avgSeconds - b.avgSeconds : rate(b) - rate(a));
122	  return [...models].sort(order).map((summary, i) => ({
123	    summary,
124	    verdict: !gated(summary)
125	      ? summary.gateFailures.length
126	        ? "❌ fails the data/premise gate"
127	        : `❌ p95 over ${P95_LIMIT_SECONDS}s`
128	      : tied(summary)
129	        ? i === 0
130	          ? "🏆 top accuracy, cheapest"
131	          : "tied on accuracy, costs more"
132	        : "less accurate",
133	  }));
134	}
