1	/**
2	 * @module scripts/bakeoff
3	 *
4	 * `npm run bakeoff -- <results.json> [more.json …]` — compares models from saved eval
5	 * results (no API calls) and writes docs/bakeoff.md (B6).
6	 *
7	 * Several files for the same model are pooled (e.g. a screen run + a --repeat=2 run).
8	 * Files graded by a judge other than JUDGE_MODEL (made with --rejudge and another
9	 * JUDGE_MODEL) go into the cross-judge table (B3) instead of the ranking.
10	 *
11	 * Winner rule (B4): 1) gate: zero failures on premise/data checks and p95 ≤ 30 s;
12	 * 2) accuracy: pass rate, where within 2 case-runs of the best counts as a tie;
13	 * 3) cheapest per answer among the tied; 4) fastest as the final tiebreak.
14	 */
15	import { readFileSync, writeFileSync } from "node:fs";
16	import { getJudgeEnv } from "../src/core/config/env";
17	import { baseModel, judgeReliable, P95_LIMIT_SECONDS, rankModels, summarize, TIE_BAND_RUNS, type ResultsFile } from "../evals/lib/bakeoff";
18	
19	/** Formats a number to fixed decimals. */
20	const f = (n: number, d = 1) => n.toFixed(d);
21	
22	/** Formats a USD amount per answer. */
23	const usd = (n: number | null) => (n === null ? "n/a" : n < 0.01 ? `$${n.toFixed(4)}` : `$${n.toFixed(3)}`);
24	
25	/** Runs the comparison. */
26	function main(): void {
27	  const paths = process.argv.slice(2).filter((a) => !a.startsWith("--"));
28	  if (paths.length === 0) throw new Error("Usage: npm run bakeoff -- <evals/results/…json> [more.json …]");
29	  const primaryJudge = getJudgeEnv().JUDGE_MODEL;
30	  const files = paths.map((p) => JSON.parse(readFileSync(p, "utf8")) as ResultsFile);
31	  const modelOf = (f: ResultsFile) => baseModel(f.label);
32	  const primary = files.filter((f) => f.judge === primaryJudge);
33	  const cross = files.filter((f) => f.judge && f.judge !== primaryJudge);
34	  /** Groups files by a key. */
35	  const groupBy = (list: ResultsFile[], key: (f: ResultsFile) => string) => {
36	    const map = new Map<string, ResultsFile[]>();
37	    for (const file of list) map.set(key(file), [...(map.get(key(file)) ?? []), file]);
38	    return map;
39	  };
40	
41	  const byModel = new Map<string, ResultsFile[]>();
42	  for (const file of primary) byModel.set(modelOf(file), [...(byModel.get(modelOf(file)) ?? []), file]);
43	  const ranked = rankModels([...byModel].map(([model, fs]) => summarize(model, fs)));
44	
45	  const rows = ranked.map(
46	    ({ summary: m, verdict }) =>
47	      `| ${m.model} | ${m.passed}/${m.caseRuns} | ${m.gateFailures.length} | ${m.judgeFailures} | ${usd(m.costPerAnswer)} | ` +
48	      `${f(m.avgSeconds)} / ${f(m.p95Seconds)} | ${f(m.avgToolCalls)} | ${m.duplicateCalls} | ${m.untraced} | ${m.retries} | ` +
49	      `${m.faithful === null ? "n/a" : f(m.faithful)} | ${verdict} |`,
50	  );
51	  const failures = ranked
52	    .filter(({ summary: m }) => m.failedCases.length)
53	    .map(({ summary: m }) => `- **${m.model}**: ${m.failedCases.join(", ")}${m.gateFailures.length ? ` · gate: ${m.gateFailures.join("; ")}` : ""}`);
54	  const crossRows = [...groupBy(cross, (file) => file.judge!)].flatMap(([judgeId, judgeFiles]) => {
55	    const reliable = judgeReliable(judgeFiles);
56	    return [...groupBy(judgeFiles, modelOf)].map(([model, modelFiles]) => {
57	      const s = summarize(model, modelFiles);
58	      const main = byModel.get(model) ? summarize(model, byModel.get(model)!) : null;
59	      return (
60	        `| ${judgeId} ${reliable ? "✅" : "❌ unreliable, ignore"} | ${model} | ${s.passed}/${s.caseRuns} | ${main ? `${main.passed}/${main.caseRuns}` : "n/a"} | ` +
61	        `${s.judgeFailures} | ${main ? main.judgeFailures : "n/a"} | ${s.faithful === null ? "n/a" : f(s.faithful)} | ${s.judgeInconsistent} |`
62	      );
63	    });
64	  });
65	
66	  const markdown = `# Model bakeoff
67	
68	Generated by \`npm run bakeoff\` from saved eval runs (same prompt, same 13 cases, no per-model tuning).
69	Rule (D107): **gate** (zero premise/data check failures, p95 ≤ ${P95_LIMIT_SECONDS}s) → **accuracy** (within ${TIE_BAND_RUNS} case-runs of the best = tie) → **cost per answer** → **speed**.
70	
71	| Model | Cases passed | Gate fails | Judge fails | Cost / answer | Avg / p95 s | Tool calls | Dups | Untraced | Retries | Faithful (1–5) | Verdict |
72	|---|---|---|---|---|---|---|---|---|---|---|---|
73	${rows.join("\n")}
74	
75	${failures.length ? `## Failed cases\n${failures.join("\n")}\n` : ""}
76	${
77	  crossRows.length
78	    ? `## Cross-judge check (B3)
79	The same answers re-graded by a judge from another provider, to catch a judge favoring its own model family.
80	A judge counts as reliable only if it grades all 3 planted answers right in every run and never contradicts itself (D109).
81	
82	| Cross judge | Model | Passed (cross) | Passed (${primaryJudge}) | Judge fails (cross) | Judge fails (${primaryJudge}) | Faithful (cross) | Self-contradicting |
83	|---|---|---|---|---|---|---|---|
84	${crossRows.join("\n")}
85	`
86	    : ""
87	}`;
88	  console.log(markdown);
89	  if (process.argv.includes("--publish") || process.env.npm_config_publish === "true") {
90	    writeFileSync("docs/bakeoff.md", markdown);
91	    console.log("Written to docs/bakeoff.md");
92	  }
93	}
94	
95	try {
96	  main();
97	} catch (error) {
98	  console.error(error instanceof Error ? error.message : error);
99	  process.exit(1);
100	}
101

1	/**
2	 * @module scripts/eval-guard
3	 *
4	 * `npm run eval:guard` — runs the guard eval set (evals/guardCases.ts) through the
5	 * production guard (D118) and checks every case is allowed or declined as expected.
6	 * Also reports the margins around the cutoffs, so tuning them is a measured choice.
7	 *
8	 *   npm run eval:guard                 one pass (~35 Jev calls, well under 1 cent)
9	 *   npm run eval:guard -- --repeat=3   Jev isn't fully deterministic: check stability
10	 *   npm run eval:guard -- --publish    also write docs/guard-evals.md
11	 *
12	 * Exit code 1 when any case gets the wrong decision (or Jev fails and the guard fails open).
13	 */
14	import { writeFileSync } from "node:fs";
15	import { getJevEnv } from "../src/core/config/env";
16	import { GUARD_TIMEOUT_MS } from "../src/core/config/timeouts";
17	import { listActiveHubs } from "../src/core/db/hubsRepository";
18	import { GUARD_CONFIG, runGuard, type GuardVerdict } from "../src/core/guard/jevGuard";
19	import { GUARD_CASES, type GuardCase } from "../evals/guardCases";
20	
21	/** Reads `--name=value` (or PowerShell's `npm_config_name`). */
22	function flag(name: string): string | undefined {
23	  const arg = process.argv.find((a) => a.startsWith(`--${name}=`));
24	  return arg ? arg.slice(name.length + 3) : process.env[`npm_config_${name}`];
25	}
26	
27	/** Reads a boolean `--name` flag. */
28	const has = (name: string) => process.argv.includes(`--${name}`) || process.env[`npm_config_${name}`] === "true";
29	
30	/** Formats a probability range over repeats. */
31	const range = (xs: number[]) => (xs.length ? `${Math.min(...xs).toFixed(2)}–${Math.max(...xs).toFixed(2)}` : "n/a");
32	
33	/** Runs the guard eval. */
34	async function main(): Promise<void> {
35	  const repeat = Math.max(1, Number(flag("repeat") ?? 1));
36	  const env = getJevEnv();
37	  const hubNames = (await listActiveHubs()).map((hub) => `${hub.name}, ${hub.state}`);
38	  console.log(`Guard eval: ${GUARD_CASES.length} cases × ${repeat} on ${env.JEV_MODEL} (decline if on-topic < ${GUARD_CONFIG.inScopeCutoff} or manipulation > ${GUARD_CONFIG.manipulationCutoff})…`);
39	
40	  const results: { c: GuardCase; verdicts: GuardVerdict[] }[] = [];
41	  for (const c of GUARD_CASES) {
42	    const verdicts: GuardVerdict[] = [];
43	    for (let i = 0; i < repeat; i++) {
44	      verdicts.push(await runGuard({ message: c.message, history: c.history, hubNames }, { apiKey: env.OPENROUTER_API_KEY, model: env.JEV_MODEL }));
45	    }
46	    results.push({ c, verdicts });
47	  }
48	
49	  const rows = results.map(({ c, verdicts }) => {
50	    const ok = verdicts.every((v) => !v.failedOpen && v.decision === c.expected);
51	    const inScope = verdicts.flatMap((v) => (v.scores ? [v.scores.inScope] : []));
52	    const manip = verdicts.flatMap((v) => (v.scores ? [v.scores.manipulation] : []));
53	    return { c, ok, inScope, manip, got: [...new Set(verdicts.map((v) => (v.failedOpen ? "FAILED OPEN" : v.decision)))].join("/") };
54	  });
55	  for (const r of rows) {
56	    console.log(
57	      `${r.ok ? "✅" : "❌"} ${r.c.expected.padEnd(7)} ${(r.c.history.length ? "follow-up" : "first").padEnd(9)} ${r.c.kind.padEnd(12)} ${r.c.id.padEnd(16)} on-topic ${range(r.inScope)}  manipulation ${range(r.manip)}${r.ok ? "" : `  → got ${r.got}`}`,
58	    );
59	  }
60	
61	  const allow = rows.filter((r) => r.c.expected === "allow");
62	  const passed = rows.filter((r) => r.ok).length;
63	  const lowestAllowed = Math.min(...allow.flatMap((r) => r.inScope));
64	  const highestAllowedManip = Math.max(...allow.flatMap((r) => r.manip));
65	  const ms = results.flatMap((r) => r.verdicts.map((v) => v.ms)).sort((a, b) => a - b);
66	  const p95 = ms[Math.floor(ms.length * 0.95)] ?? 0;
67	  const summary = [
68	    `${passed}/${rows.length} cases got the right decision${repeat > 1 ? ` in all ${repeat} runs` : ""}.`,
69	    `Margins: lowest on-topic score of a message that must pass = ${lowestAllowed.toFixed(2)} (cutoff ${GUARD_CONFIG.inScopeCutoff}); highest manipulation score of a message that must pass = ${highestAllowedManip.toFixed(2)} (cutoff ${GUARD_CONFIG.manipulationCutoff}).`,
70	    `Latency: median ${ms[Math.floor(ms.length / 2)]} ms, p95 ${p95} ms (timeout ${GUARD_TIMEOUT_MS} ms).`,
71	  ];
72	  console.log(`\n${passed === rows.length ? "🏆" : "⚠️ "} ${summary.join("\n   ")}`);
73	
74	  if (has("publish")) {
75	    const table = rows
76	      .map(
77	        (r) =>
78	          `| ${r.ok ? "✅" : "❌"} | \`${r.c.id}\` | ${r.c.message.replace(/\|/g, "\\|")} | ${r.c.history.length ? "follow-up" : "first"} | ${r.c.kind} | ${r.c.expected} | ${range(r.inScope)} | ${range(r.manip)} |`,
79	      )
80	      .join("\n");
81	    writeFileSync(
82	      "docs/guard-evals.md",
83	      `# Guard eval results
84	
85	Latest run: **${env.JEV_MODEL}** · ${new Date().toISOString().slice(0, 16).replace("T", " ")} UTC · ${repeat} run(s) per case.
86	Run it yourself: \`npm run eval:guard\`. The cases are in [evals/guardCases.ts](../evals/guardCases.ts), and how the guard works is in
87	[design.md](design.md#9-errors-security-and-limits).
88	
89	The guard declines a message when Jev's probability that it's on topic is below **${GUARD_CONFIG.inScopeCutoff}**, or its probability that it
90	tries to change the assistant's rules is above **${GUARD_CONFIG.manipulationCutoff}**. Follow-ups are judged together with the last
91	${GUARD_CONFIG.historyTurns} turns.
92	
93	${summary.map((s) => `- ${s}`).join("\n")}
94	
95	| | Case | Message | Turn | Kind | Expected | On-topic P | Manipulation P |
96	|---|---|---|---|---|---|---|---|
97	${table}
98	`,
99	    );
100	    console.log("Written to docs/guard-evals.md");
101	  }
102	  if (passed !== rows.length) process.exit(1);
103	}
104	
105	main().catch((error: unknown) => {
106	  console.error(error instanceof Error ? error.message : error);
107	  process.exit(1);
108	});
