/**
 * @module scripts/compute-fema-anchors
 *
 * Recomputes the FEMA "100" anchors (D47): the 95th percentile of each signal
 * across all US counties where FEMA rates the hazard. Tornado is per area (D53);
 * inland flood is per area with the area floored at the median US county (D123).
 *
 * `npm run fema:anchors` prints the values; they are then frozen by hand in
 * src/core/scoring/config.ts (FEMA_ANCHORS_P95) so scores never shift silently
 * when FEMA updates its data. Re-run when a new NRI version is released.
 */
import { fetchJsonWithRetry } from "../src/core/data/http";
import { percentile, round } from "../src/core/utils/stats";

const LAYER =
  "https://services.arcgis.com/XG15cJAlne2vxtgt/arcgis/rest/services/National_Risk_Index_Counties/FeatureServer/0/query";
const AFREQ_FIELDS = ["HRCN", "TRND", "HAIL", "IFLD", "CFLD", "ISTM", "WNTW", "CWAV", "HWAV", "SWND"] as const;

type CountyRow = Record<string, number | string | null>;

/**
 * Downloads every county row (paged, 2,000 per page).
 * @returns all county attribute rows.
 */
async function fetchAllCounties(): Promise<CountyRow[]> {
  const rows: CountyRow[] = [];
  for (let offset = 0; ; offset += 2_000) {
    const params = new URLSearchParams({
      where: "1=1",
      outFields: ["STCOFIPS", "NRI_VER", "AREA", ...AFREQ_FIELDS.map((f) => `${f}_AFREQ`)].join(","),
      returnGeometry: "false",
      f: "json",
      resultOffset: String(offset),
      resultRecordCount: "2000",
    });
    const page = (await fetchJsonWithRetry({
      url: `${LAYER}?${params.toString()}`,
      boundary: "fema",
      functionName: "fetchAllCounties",
      errorName: "FemaFetchError",
    })) as { features: { attributes: CountyRow }[]; exceededTransferLimit?: boolean };
    rows.push(...page.features.map((feature) => feature.attributes));
    if (!page.exceededTransferLimit) return rows;
  }
}

/** Prints the p95 anchors. */
async function main(): Promise<void> {
  const rows = await fetchAllCounties();
  console.log(`Counties: ${rows.length} · NRI version: ${rows[0]?.NRI_VER}`);
  // Inland flood's area floor (D123): the median US county area → INLAND_FLOOD_AREA_FLOOR_SQ_MI.
  const medianArea = percentile(rows.map((r) => Number(r.AREA)).filter((a) => a > 0), 0.5);
  console.log(`${"Median county area".padEnd(34)} = ${round(medianArea, 1)} sq mi  (INLAND_FLOOD_AREA_FLOOR_SQ_MI)`);
  for (const field of AFREQ_FIELDS) {
    const rated = rows.filter((r) => r[`${field}_AFREQ`] !== null && Number(r.AREA) > 0);
    const freq = (r: CountyRow) => Number(r[`${field}_AFREQ`]);
    // Scored per 1,000 sq mi: tornado per county area (D53), inland flood per area floored at the median (D123).
    const [label, values] =
      field === "TRND"
        ? ["TRND per 1,000 sq mi", rated.map((r) => (freq(r) / Number(r.AREA)) * 1_000)]
        : field === "IFLD"
          ? ["IFLD per 1,000 sq mi (area ≥ median)", rated.map((r) => (freq(r) / Math.max(Number(r.AREA), medianArea)) * 1_000)]
          : [`${field}_AFREQ`, rated.map(freq)];
    console.log(`${label.padEnd(34)} p95 = ${round(percentile(values, 0.95), 3)}  (n=${values.length})`);
  }
}

main().catch((error: unknown) => {
  console.error(error instanceof Error ? error.message : error);
  process.exit(1);
});
/**
 * @module scripts/export-session
 *
 * Exports the Claude Code session log(s) into docs/session/ — scrubbed of
 * private details — as required by the assignment ("the full session with the
 * AI agent you worked with").
 *
 * Usage:
 *   npm run session:export -- <path-to-session.jsonl> [more.jsonl ...]
 *   (or set SESSION_LOG_PATHS in .env.local, comma-separated)
 *
 * Output (written only when the leak check passes):
 *   docs/session/transcript.md     readable conversation (tool I/O truncated)
 *   docs/session/transcript.jsonl  the scrubbed conversation records, untruncated
 *
 * Every record is parsed, its private reasoning blocks removed, and every string inside it
 * scrubbed (so escaped paths are caught too). The leak check runs on the final text in
 * memory; nothing is written if it finds anything.
 */
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { homedir } from "node:os";
import { join, resolve } from "node:path";
import { buildScrubRules, findLeaks, scrubRecord } from "./session/scrub";
import { isConversationRecord, renderTranscript, withoutReasoning, type TranscriptRecord } from "./session/render";

/** Where the transcript files are written. */
const OUTPUT_DIR = resolve("docs", "session");

/** `.env.local` keys whose values are public and stay readable in the log (model ids). */
const PUBLIC_ENV_KEY = /_MODEL$/;

/** What the exporter reads from `.env.local`. */
interface LocalSettings {
  /** Values to scrub: every secret-like value plus `SESSION_SCRUB_TERMS`. */
  secretValues: string[];
  /** `SESSION_LOG_PATHS`, when set. */
  logPaths: string[];
}

/**
 * Reads `.env.local` (without loading it into the environment). Every value of 8+ characters is
 * treated as secret except model ids. `SESSION_SCRUB_TERMS` (comma-separated) holds extra
 * private words to remove, e.g. other people's usernames, so the list itself is never committed.
 * @returns the values to scrub and the log paths.
 */
function readLocalSettings(): LocalSettings {
  const envPath = resolve(".env.local");
  const settings: LocalSettings = { secretValues: [], logPaths: [] };
  if (!existsSync(envPath)) return settings;
  for (const rawLine of readFileSync(envPath, "utf8").split(/\r?\n/)) {
    const line = rawLine.trim();
    if (!line || line.startsWith("#") || !line.includes("=")) continue;
    const key = line.slice(0, line.indexOf("=")).trim();
    const rawValue = line.slice(line.indexOf("=") + 1).trim();
    const quoted = /^(["'])(.*)\1$/.exec(rawValue);
    const value = quoted ? quoted[2] : rawValue.replace(/\s+#.*$/, ""); // unquoted values may carry a trailing comment
    const list = () => value.split(",").map((item) => item.trim()).filter(Boolean);
    if (key === "SESSION_SCRUB_TERMS") settings.secretValues.push(...list().filter((term) => term.length >= 4));
    else if (key === "SESSION_LOG_PATHS") settings.logPaths = list();
    else if (!PUBLIC_ENV_KEY.test(key) && value.length >= 8) settings.secretValues.push(value);
  }
  return settings;
}

/** Entry point. */
function main(): void {
  const settings = readLocalSettings();
  const cliPaths = process.argv.slice(2);
  const inputPaths = cliPaths.length > 0 ? cliPaths : settings.logPaths;
  if (inputPaths.length === 0) {
    console.error("Usage: npm run session:export -- <session.jsonl> [more.jsonl ...]  (or set SESSION_LOG_PATHS in .env.local)");
    process.exit(1);
  }

  const rules = buildScrubRules({ homeDir: homedir(), secretValues: settings.secretValues });
  const records: TranscriptRecord[] = [];
  for (const inputPath of inputPaths) {
    const lines = readFileSync(inputPath, "utf8").split(/\r?\n/).filter(Boolean);
    lines.forEach((line, index) => {
      let record: TranscriptRecord;
      try {
        record = JSON.parse(line) as TranscriptRecord;
      } catch {
        throw new Error(`${inputPath} line ${index + 1} is not valid JSON (is the session still being written?).`);
      }
      if (!isConversationRecord(record)) return;
      const kept = withoutReasoning(record);
      if (kept) records.push(scrubRecord(kept, rules) as TranscriptRecord);
    });
  }

  const jsonl = `${records.map((record) => JSON.stringify(record)).join("\n")}\n`;
  const markdown = renderTranscript(records, "Sneakoscope — full AI coding session (scrubbed)");
  const leaks = findLeaks(`${jsonl}\n${markdown}`, { homeDir: homedir(), secretValues: settings.secretValues });
  if (leaks.length > 0) {
    console.error(`⚠️  Leak check failed, nothing was written: ${leaks.join(", ")}. Add terms to SESSION_SCRUB_TERMS or fix the scrub rules.`);
    process.exit(2);
  }

  mkdirSync(OUTPUT_DIR, { recursive: true });
  writeFileSync(join(OUTPUT_DIR, "transcript.jsonl"), jsonl);
  writeFileSync(join(OUTPUT_DIR, "transcript.md"), markdown);
  console.log(`✅ Exported ${records.length} records from ${inputPaths.length} file(s) to ${OUTPUT_DIR}`);
  console.log("🔒 Leak check passed: no emails, tokens, secret values, username or home path left.");
}

try {
  main();
} catch (error) {
  console.error(error instanceof Error ? error.message : error);
  process.exit(1);
}
import { describe, expect, it } from "vitest";
import type { FinalAnswer } from "../src/core/agent/answerSchema";
import { EVAL_CASES } from "./cases";
import { plainText } from "./lib/checks";
import type { Oracle } from "./lib/oracle";

/** Runs one case's checks on a single answer text (wording checks only need the text). */
async function wordingChecks(caseId: string, text: string) {
  const evalCase = EVAL_CASES.find((c) => c.id === caseId)!;
  const answer = { answer: text, hubsMentioned: [], dataUsed: [], outOfScope: false, meta: { toolCalls: [] } } as unknown as FinalAnswer;
  return evalCase.check([{ question: evalCase.turns[0], answer, ms: 1 }], {} as Oracle);
}

describe("plainText", () => {
  it("turns typographic quotes into plain ones", () => {
    expect(plainText("Dust storms aren’t tracked — “really”")).toBe(`Dust storms aren't tracked — "really"`);
  });
});

describe("wording checks accept correct answers in any phrasing (bakeoff false failures)", () => {
  it.each([
    "Boise is not one of the hubs covered by our weather-risk data, so I can’t assess its risk.",
    "Boise is not one of our covered hubs, so I can’t provide a weather-risk assessment for it.",
    "Boise isn't one of our hubs.",
  ])("unknown city: %s", async (text) => {
    const checks = await wordingChecks("unknown-city", text);
    expect(checks.find((c) => c.name.startsWith("says Boise"))?.pass).toBe(true);
  });

  it.each([
    "I can’t determine the Phoenix hub’s dust-storm exposure from the available risk data. Dust storms aren’t a tracked hazard.",
    "Dust storms are not a scored hazard, so the model does not provide a dust-storm frequency.",
  ])("dust storms: %s", async (text) => {
    const checks = await wordingChecks("dust-storm", text);
    expect(checks.find((c) => c.name.startsWith("says dust"))?.pass).toBe(true);
  });

  it("still fails an answer that never says Boise is outside our hubs", async () => {
    const checks = await wordingChecks("unknown-city", "Boise has moderate winter risk.");
    expect(checks.find((c) => c.name.startsWith("says Boise"))?.pass).toBe(false);
  });
});
