      ];
    },
  },
  {
    id: "dust-storm",
    title: "Hazard we don't score (dust storms)",
    turns: ["How exposed is the Phoenix hub to dust storms?"],
    check: ([r]) => {
      const base = answered([r]);
      if (!r.answer) return base;
      return [
        ...base,
        check("says dust storms aren't scored", someSentence(r.answer.answer, /\bdust/i, NOT_SCORED), "expected a plain statement, in one sentence, that dust storms aren't scored", "behavior"),
