import { readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { EVAL_CASES } from "~/Home-Assignment-Moveo/.claude/worktrees/agent-a96f11c9b9028f9e4/evals/cases";
import type { Oracle } from "~/Home-Assignment-Moveo/.claude/worktrees/agent-a96f11c9b9028f9e4/evals/lib/oracle";

const dir = "~/Home-Assignment-Moveo/evals/results";
const TEXT_CHECKS = ["Miami hurricane score matches", "Houston flood score matches", "percentage matches computed value", "says Boise isn't one of our hubs", "says dust storms aren't scored", "explains why", "names the computed top 5", "first hub named = computed #1"];
const diffs: string[] = [];
let compared = 0;
const seen = new Set<string>();
for (const name of readdirSync(dir).filter((f) => f.endsWith(".json"))) {
  const file = JSON.parse(readFileSync(join(dir, name), "utf8"));
  for (const run of file.runs) {
    const evalCase = EVAL_CASES.find((c) => c.id === run.caseId);
    if (!evalCase || !run.results.every((r: { answer: unknown }) => r.answer)) continue;
    const key = run.caseId + JSON.stringify(run.results.map((r: { answer: { answer: string } }) => r.answer.answer));
    if (seen.has(key)) continue;
    seen.add(key);
    const old = new Map<string, { pass: boolean; detail: string }>(run.checks.map((c: { name: string; pass: boolean; detail: string }) => [c.name, c]));
    const num = (n: string) => Number(/expected ([\d.]+)/.exec(old.get(n)?.detail ?? "")?.[1]);
    const oracle = {
      lastYear: 2025,
      hubs: [],
      ranking: () => [],
      level: () => "low",
      hazardScore: (hubId: string) => (hubId === "miami" ? num("Miami hurricane score matches") : num("Houston flood score matches")),
      hazardConfidence: () => "medium",
      yearPercent: async () => num("percentage matches computed value"),
    } as unknown as Oracle;
    const hubNames = [
      { id: "miami", name: "Miami" },
      { id: "houston", name: "Houston" },
      { id: "denver", name: "Denver" },
    ];
    (oracle as { hubs: unknown }).hubs = hubNames;
    let fresh;
    try {
      fresh = await evalCase.check(run.results, oracle);
    } catch (e) {
      continue;
    }
    for (const c of fresh) {
      if (!TEXT_CHECKS.includes(c.name) || !old.has(c.name) || c.name.includes("top 5") || c.name.includes("first hub")) continue;
      compared++;
      if (old.get(c.name)!.pass !== c.pass) {
        diffs.push(`${name} ${run.caseId} "${c.name}": old ${old.get(c.name)!.pass} new ${c.pass} — ${c.detail}\n   TEXT: ${run.results.at(-1).answer.answer.replace(/\n/g, " ⏎ ").slice(0, 600)}\n   DATA: ${JSON.stringify(run.results.at(-1).answer.dataUsed).slice(0, 400)}`);
      }
    }
  }
}
console.log(`compared ${compared} checks on ${seen.size} distinct answers; ${diffs.length} differ`);
console.log(diffs.join("\n"));

